-- Table structure for table `comments`

DROP TABLE IF EXISTS `comments`;
CREATE TABLE `comments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `topic_id` int NOT NULL COMMENT '话题ID',
  `author_id` int NOT NULL COMMENT '作者ID',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评论内容',
  `parent_id` int DEFAULT NULL COMMENT '父评论ID（用于回复功能）',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `topic_id` (`topic_id`) USING BTREE,
  KEY `author_id` (`author_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE,
  CONSTRAINT `comments_ibfk_1` FOREIGN KEY (`topic_id`) REFERENCES `topics` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `comments_ibfk_2` FOREIGN KEY (`author_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `comments_ibfk_3` FOREIGN KEY (`parent_id`) REFERENCES `comments` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Table structure for table `generation_request`

DROP TABLE IF EXISTS `generation_request`;
CREATE TABLE `generation_request` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL COMMENT '提交用户id',
  `user_name` varchar(64) DEFAULT NULL COMMENT '提交用户名',
  `gen_events` text COMMENT '要生成的事件描述',
  `source_file` varchar(255) DEFAULT NULL COMMENT '上传的报告文件名(存 files/generation-requests/)',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `status` varchar(16) DEFAULT '待处理',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `gen_status` tinyint DEFAULT '0' COMMENT '生成状态:0生成中 1成功 2失败',
  `output_path` varchar(512) DEFAULT NULL COMMENT '生成输出目录(files/generations/用户/剧本)',
  `gen_log` varchar(1000) DEFAULT NULL COMMENT '生成日志/失败原因摘要',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

